# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PEYGAMBERLERE İMAN (NÜBÜVVET) VE PEYGAMBERLERİN SIFATLARI</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">PEYGAMBERLERİN 5 TEMEL SIFATI</text>\n  <text x="35" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">1. Sıdk (Doğruluk): Daima doğru sözlü olmaları.</text>\n  <text x="35" y="118" font-size="11" font-weight="bold" fill="#1e3a8a">2. Emanet (Güvenilirlik): Güvenilir olmaları.</text>\n  <text x="35" y="142" font-size="11" font-weight="bold" fill="#1e3a8a">3. Fetanet (Zekâ): Üstün akıl ve kavrayış sahibi olmaları.</text>\n  <text x="35" y="166" font-size="11" font-weight="bold" fill="#1e3a8a">4. İsmet (Günahsızlık): Günahtan korunmuş olmaları.</text>\n  <text x="35" y="190" font-size="11" font-weight="bold" fill="#1e3a8a">5. Tebliğ: Vahyi eksiksizce insanlara iletmeleri.</text>\n  <text x="35" y="218" font-size="10.5" font-weight="bold" fill="#b91c1c">• Hz. Muhammed (sav): Hâtemü\'l-Enbiyâ (Son Peygamber)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">NÜBÜVVET KAVRAMLARI</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#14532d">• Resul ve Nebi:</text>\n  <text x="383" y="112" font-size="10.5" fill="#166534">Yeni bir kitap ve şeriat verilen elçiye Resul; önceki</text>\n  <text x="383" y="128" font-size="10.5" fill="#166534">şeriatı tebliğ edene Nebi denir (Her resul aynı zamanda nebidir).</text>\n  <text x="375" y="156" font-size="11" font-weight="bold" fill="#14532d">• Mucize:</text>\n  <text x="383" y="172" font-size="10.5" fill="#166534">Peygamberlerin nübüvvet iddiasını doğrulamak için</text>\n  <text x="383" y="188" font-size="10.5" fill="#166534">Allah\'ın izniyle gösterdikleri olağanüstü olaylardır.</text>\n  <text x="375" y="216" font-size="10.5" font-weight="bold" fill="#15803d">• Kur\'an-ı Kerim\'de 25 peygamberin ismi geçmektedir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AHİRETE İMAN AŞAMALARI VE KADER - KAZA İNANCI</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">AHİRET HAYATININ MERHALELERİ</text>\n  <text x="35" y="94" font-size="10.5" font-weight="bold" fill="#78350f">1. Ölüm ve Berzah: Kabir hayatı (dünya ile ahiret arası).</text>\n  <text x="35" y="116" font-size="10.5" font-weight="bold" fill="#78350f">2. Kıyamet: İsrafil\'in Sûr\'a ilk üflemesiyle evrenin sonu.</text>\n  <text x="35" y="138" font-size="10.5" font-weight="bold" fill="#78350f">3. Ba\'s: Sûr\'a ikinci üfleyişle yeniden diriliş.</text>\n  <text x="35" y="160" font-size="10.5" font-weight="bold" fill="#78350f">4. Haşir ve Mahşer: Hesap için toplanma ve meydan.</text>\n  <text x="35" y="182" font-size="10.5" font-weight="bold" fill="#78350f">5. Hesap, Mizan ve Sırat: Amel defteri ve adalet terazisi.</text>\n  <text x="35" y="204" font-size="10.5" font-weight="bold" fill="#15803d">6. Cennet (ebedî mükâfat) ve Cehennem (ceza yurdu).</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">KADER VE KAZA İNANCI</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#581c87">• Kader (Ölçü ve Plan):</text>\n  <text x="383" y="112" font-size="10.5" fill="#6b21a8">Allah\'ın sonsuz ilmi ve kudretiyle evrendeki her şeyi</text>\n  <text x="383" y="128" font-size="10.5" fill="#6b21a8">belli bir ölçü, düzen ve uyuma göre takdir etmesidir.</text>\n  <text x="375" y="156" font-size="11" font-weight="bold" fill="#581c87">• Kaza (Gerçekleşme):</text>\n  <text x="383" y="172" font-size="10.5" fill="#6b21a8">Allah\'ın takdir ettiği olayların zamanı gelince yaratılmasıdır.</text>\n  <text x="375" y="198" font-size="10.5" font-weight="bold" fill="#b91c1c">• Cüz\'î İrade ve Sorumluluk: İnsan akıl ve özgür iradesiyle</text>\n  <text x="383" y="214" font-size="10.5" font-weight="bold" fill="#b91c1c">seçim yapar; tedbir alıp Allah\'a güvenmeye TEVEKKÜL denir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İMANIN BİREYE VE TOPLUMA KAZANDIRDIKLARI (DKAB.9.2.3)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. İMANIN BİREYE KAZANDIRDIKLARI</text>\n  <text x="35" y="96" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Anlam ve Gaye: Hayatın amacını ve varoluşu anlamlandırır.</text>\n  <text x="35" y="120" font-size="10.5" font-weight="bold" fill="#1e3a8a">• İç Huzur ve Güven: Kalplere sekinet ve ümit verir (Ra\'d, 28).</text>\n  <text x="35" y="144" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Özgürlük ve İzzet: Kula kulluktan ve hurafeden kurtarır.</text>\n  <text x="35" y="168" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Sabır ve Metanet: Zorluklar karşısında direnç kazandırır.</text>\n  <text x="35" y="192" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Öz Denetim (Takva): Kimse görmese de günahtan korur.</text>\n  <text x="35" y="216" font-size="10.5" font-weight="bold" fill="#b91c1c">• Salih Amel Bilinci: İmanı güzel davranışlarla bütünleştirir.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. İMANIN TOPLUMA KAZANDIRDIKLARI</text>\n  <text x="375" y="96" font-size="10.5" font-weight="bold" fill="#14532d">• Adalet ve Hakkaniyet: Kul hakkına riayeti yerleştirir.</text>\n  <text x="375" y="120" font-size="10.5" font-weight="bold" fill="#14532d">• Güven Toplumu: Emanete sadakati ve dürüstlüğü yayar.</text>\n  <text x="375" y="144" font-size="10.5" font-weight="bold" fill="#14532d">• Kardeşlik ve Dayanışma: Müminleri kardeş kılar (Hucurât, 10).</text>\n  <text x="375" y="168" font-size="10.5" font-weight="bold" fill="#14532d">• Merhamet ve Yardımlaşma: İnfak ve zekâtla yoksulu gözetir.</text>\n  <text x="375" y="192" font-size="10.5" font-weight="bold" fill="#14532d">• Suç Oranlarının Azalması: Ahiret hesabıyla kötülüğü önler.</text>\n  <text x="375" y="216" font-size="10.5" font-weight="bold" fill="#15803d">• Toplumsal Barış: Sevgi, saygı ve hoşgörüyü güçlendirir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
